-- Schede nuove dalle pagine RHS (controllo periodico del 26/11/2026): 22 specie del catalogo senza
-- nessuna scheda. Testi in italiano scritti a mano (scripts/rhs-import/dati/), in bozza e mostrate.
-- Generata da scripts/rhs-import/schede_nuove.py. Rollback: scripts/rhs-import/rollback_rhs_schede_nuove_lotto5.sql
do $$ begin
  if exists (select 1 from public.schede where taxon_id in ('52239156-a77e-4ec4-bde8-27d95a8160d8'::uuid, '7055a91d-148a-4c35-84a0-9043c8ea6102'::uuid, 'e7a5b4d7-90df-4c96-b0d6-38263bd8d477'::uuid, '602ba8e5-1f08-4bb4-9595-50dc497d5be2'::uuid, '013eff8a-95f3-4cb2-a189-8c1e1449e96a'::uuid, 'bf4ccf57-ded7-4f22-9fc7-1e908bbc5800'::uuid, '4b097e2a-ec83-4b86-b81d-840bd3ad8092'::uuid, '360166ac-7939-46d7-aabb-1bcf08b09789'::uuid, '4e2290f7-3257-4d40-84eb-fe227a36543b'::uuid, 'd7f098a0-fc7b-4ab7-929a-67d20c4a6290'::uuid, '07097b8c-c226-4e6f-a730-ee4efc9889a7'::uuid, '2afbfceb-16fb-422b-96a5-cb3e003237b3'::uuid, 'eded20a4-674e-449c-8f31-afd165faaa4a'::uuid, 'f3461241-0dc8-4fb2-b198-ee04d68cff82'::uuid, '4035f7bb-b937-4739-ac21-ddf879714a7e'::uuid, '095907bc-6669-47e1-8deb-4b2d658879a8'::uuid, 'd6ec7e81-54a2-404e-9d97-23f93de685d0'::uuid, 'fc980c19-d382-45b1-b3e6-6c576764fedf'::uuid, 'ea589bf7-0f68-4d0e-8a54-65f4d96c20d9'::uuid, 'e62e6ca5-1914-484f-af38-5197ecd63992'::uuid, '78dc34b3-33fb-4d93-adaa-9d54bc21a257'::uuid, '3042e3b6-f059-4ce8-904d-d3b3c11b74ad'::uuid)) then
    raise exception 'una di queste specie ha già una scheda: lotto da rigenerare';
  end if;
end $$;
insert into public.schede (id, taxon_id, fonti, descrizione, descrizione_originale, lingua_descrizione, esigenze,
  ciclo_vitale, alert, stato_verifica, mostrata, forma, nota) values
('ff2709fd-258d-5368-a7f0-d985e7f9529b'::uuid, '52239156-a77e-4ec4-bde8-27d95a8160d8'::uuid, array['RHS (rhs.org.uk) — Allium ostrowskianum']::text[], 'Aglio ornamentale della famiglia delle Amarillidacee, originario dell''Asia centrale. Molti botanici lo considerano la stessa pianta di Allium oreophilum, o una sua varietà, e nei vivai si trova con entrambi i nomi: l''aspetto e le cure sono le stesse. È una bulbosa compatta, alta e larga una ventina di centimetri, con poche foglie strette, verde medio, lunghe fino a 15 cm. A inizio estate porta ombrelle lasse e bombate di non più di dieci fiori rosa porpora vivo, con i tepali percorsi da una nervatura centrale più scura; la cultivar ''Zwanenburg'' ha fiori rosa carminio più intenso. Vuole pieno sole e un terreno fertile e ben drenato; dove la terra è argillosa e resta zuppa d''inverno è meglio coltivarlo in vaso. Adatto al giardino roccioso, alle bordure e ai vasi, attira gli insetti impollinatori.', 'Compact bulbous perennial growing to a height and spread of 20cm. It has narrow, mid-green leaves to 15cm long, and in early summer bears loose, domed heads of up to ten bright pink-purple flowers, the tepals with a darker mid-rib', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere attaccato dalla mosca minatrice del porro e dalla mosca della cipolla; Malattie: può soffrire di marciume bianco della cipolla e di peronospora della cipolla', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potature, a parte togliere gli steli sfioriti e il fogliame vecchio', 'Propagazione: per seme in contenitore in cassone freddo, appena maturo o in primavera; in alternativa, in autunno si staccano i bulbilli']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 26483'),
('d7e3351f-033a-51a6-8ea9-d1b1e16b7c2f'::uuid, '7055a91d-148a-4c35-84a0-9043c8ea6102'::uuid, array['RHS (rhs.org.uk) — Castilleja crista-galli']::text[], 'Castilleja della famiglia delle Orobancacee, originaria del Nord America. È una perenne semiparassita, che in natura trae parte del nutrimento dalle radici di altre piante, alta circa 25 cm, con fusti eretti e foglie strette. In estate, in cima ai fusti, porta mazzi di brattee rosso arancio, verde mela alla base, tra cui spuntano i fiori rossi: sono le brattee, come in un pennello intinto nel colore, a dare spettacolo. Vuole pieno sole e un terreno fresco ma ben drenato; si coltiva bene anche in vaso, e una pianta ospite non è indispensabile.', 'A semi-parasitic, herbaceous perennial to 25cmwith upright stems carrying narrow leaves and, in summer, terminal clusters of red-orange bracts, apple green at the base, with red flowers', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 208406'),
('fb833adb-1c3a-53fe-a5ff-f5ac08c97d5a'::uuid, 'e7a5b4d7-90df-4c96-b0d6-38263bd8d477'::uuid, array['RHS (rhs.org.uk) — Colutea brevialata']::text[], 'Vescicaria della famiglia delle Fabacee, originaria dell''Europa meridionale e vicina alla comune Colutea arborescens. È un arbusto vigoroso, alto e largo fino a 3 m, con foglie pennate verde chiaro; in estate porta fiori gialli a farfalla larghi 2 cm, seguiti da baccelli gonfi come vesciche, lunghi fino a 8 cm. Vuole pieno sole e cresce anche su terreni poveri e asciutti, in posizioni esposte.', 'A vigorous shrub to 3m, with pale green pinnate leaves and yellow flowers 2cm across, followed by bladder-like fruits to 8cm in length', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: richiede pochissima potatura: si tolgono solo i rami secchi o rovinati', 'Propagazione: per seme o per talea di legno tenero']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 213790'),
('d492d5d3-bad5-5132-b69b-77163a4418bf'::uuid, '602ba8e5-1f08-4bb4-9595-50dc497d5be2'::uuid, array['RHS (rhs.org.uk) — Corylopsis gotoana Makino']::text[], 'Arbusto della famiglia delle Amamelidacee, originario del Giappone, vicino a Corylopsis glabrescens. È un arbusto deciduo e allargato, che può raggiungere i 6 m, con foglie largamente ovali, verde scuro di sopra e grigio azzurro di sotto. A metà primavera, sui rami ancora spogli, pendono racemi di piccoli fiori giallo pallido e profumati; in autunno il fogliame può diventare giallo vivo. Cresce in terreno acido, a mezz''ombra, fresco ma ben drenato; le gelate tardive possono rovinare i fiori, per cui conviene un luogo riparato.', 'A spreading shrub to 6m in height, with broadly oval leaves, blue-grey beneath and dark green above.  Pendulous racemes of small, fragrant, pale-yellow flowers appear in mid-spring on bare stems.  Foliage may turn a bright yellow in autumn', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 4-8m, diffusione 2.5-4m', 'Potatura: richiede pochissima potatura: subito dopo la fioritura si tolgono i rami secchi o rovinati', 'Propagazione: per seme in contenitore all''aperto in autunno, per talea di legno tenero in estate o per propaggine in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 25687'),
('a2c8aea3-7f82-5f33-96ac-dc409b99a58f'::uuid, '013eff8a-95f3-4cb2-a189-8c1e1449e96a'::uuid, array['RHS (rhs.org.uk) — Corylopsis veitchiana']::text[], 'Arbusto della famiglia delle Amamelidacee, originario della Cina centrale. È un grande arbusto deciduo, alto da 2,5 a 4 m, con foglie strettamente ovate. A inizio primavera, sui rami ancora spogli, pendono piccoli racemi lunghi fino a 4 cm di fiori giallo chiaro, con le antere rosse. Cresce in terreno acido, a mezz''ombra, fresco ma ben drenato; le gelate tardive possono rovinare i fiori, per cui conviene un luogo riparato.', 'A large deciduous shrub with narrowly ovate leaves and small light yellow flowers in drooping racemes to 4cm in length, on bare shoots; anthers red', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: richiede pochissima potatura: subito dopo la fioritura si tolgono i rami secchi o rovinati', 'Propagazione: per seme in contenitore all''aperto in autunno, per talea di legno tenero in estate o per propaggine in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 4508'),
('d2545349-9f29-5a11-a181-67de74443025'::uuid, 'bf4ccf57-ded7-4f22-9fc7-1e908bbc5800'::uuid, array['RHS (rhs.org.uk) — Dictamnus dasycarpus']::text[], 'Dittamo della famiglia delle Rutacee, originario dell''Asia orientale, parente stretto della frassinella (Dictamnus albus) dei nostri boschi. È una perenne eretta, alta fino a 90 cm, con foglie pennate e aromatiche; in estate porta spighe di fiori chiari, larghi 2,5 cm, con stami vistosi e sporgenti. Vuole un terreno ben drenato e mediamente fertile, al sole o a mezz''ombra.', 'An erect herbaceous perennial to 90cm, with aromatic, pinnate leaves and spikes of white flowers 2.5cm in width, with prominent stamens', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: in autunno si taglia alla base', 'Propagazione: per seme in vasi in cassone freddo, appena maturo o a inizio primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 28611'),
('04d9b0ef-4e6e-5d41-80da-012012b7ea36'::uuid, '4b097e2a-ec83-4b86-b81d-840bd3ad8092'::uuid, array['RHS (rhs.org.uk) — Helianthemum alpestre serpyllifolium']::text[], 'Eliantemo di montagna della famiglia delle Cistacee, diffuso sui monti dell''Europa meridionale e centrale, Alpi e Appennini compresi. Molti botanici, e la flora d''Italia del Pignatti, lo considerano una sottospecie di Helianthemum oelandicum (Helianthemum oelandicum subsp. alpestre): l''aspetto e le cure sono le stesse. È un piccolo arbusto sempreverde, prostrato e molto ramificato, alto di solito non più di una decina di centimetri, che si allarga in cuscinetti con piccole foglie strette, opposte. Tra la tarda primavera e l''estate si copre di piccoli fiori gialli a coppa aperta, riuniti in brevi racemi. Vuole pieno sole e un terreno ben drenato, da neutro a calcareo, anche povero; è adatto al giardino roccioso, ai muretti a secco, alle scarpate e al bordo delle aiuole, come tappezzante.', 'A low-growing, spreading evergreen shrub to around 40cm in height with small, mid-green linear leaves.  Masses of small, single, yellow flowers appear in late spring to summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si accorcia tutta la pianta tagliando gli steli fioriti, per mantenerla densa e compatta, senza tagliare nel legno vecchio', 'Propagazione: per talea di legno tenero a fine primavera o a inizio estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 63504'),
('64a1af23-c094-59c3-9b07-f650ebc41c8a'::uuid, '360166ac-7939-46d7-aabb-1bcf08b09789'::uuid, array['RHS (rhs.org.uk) — Hydrangea cinerea ''Sterilis''']::text[], 'Ortensia della famiglia delle Idrangeacee, originaria degli Stati Uniti sud-orientali. Molti botanici la considerano una sottospecie di Hydrangea arborescens (Hydrangea arborescens subsp. discolor), di cui ha l''aspetto e le cure. È un arbusto deciduo e cespuglioso, di portamento arrotondato, che in coltura raggiunge di solito un metro e mezzo d''altezza e di larghezza. Le foglie sono largamente ovate e dentate, verdi sopra e grigie sotto per una fine peluria, il carattere che le dà il nome. In estate porta corimbi di piccoli fiori bianchi; nella cultivar ''Sterilis'' le infiorescenze sono teste arrotondate, fitte di fiori sterili. Vuole un terreno fresco ma ben drenato, a mezz''ombra, oppure al sole se la terra resta sempre umida; nei terreni calcarei conviene aggiungere sostanza organica. Fiorisce sui rami dell''anno, e anche dopo una potatura severa.', 'A bushy, deciduous shrub to 1.5m high, with a rounded habit and broadly ovate, toothed green leaves with fine grey hairs on the undersides. Produces rounded heads densely packed with small white flowers in late summer', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, miridi, ragnetto rosso, nematodi del fusto, oziorrinco e cocciniglie; Malattie: può essere soggetta a maculatura fogliare, oidio, muffa grigia e, raramente, ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: si lasciano i fiori secchi sulla pianta durante l''inverno, a protezione delle gemme; a inizio primavera si tagliano fino alla prima coppia di gemme robuste sotto il fiore e si tolgono alla base uno o due dei rami più vecchi', 'Propagazione: per talea di legno tenero a inizio estate o per talea legnosa in inverno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 8908'),
('b08d9833-4862-5064-bcd0-10ae6537ec2b'::uuid, '4e2290f7-3257-4d40-84eb-fe227a36543b'::uuid, array['RHS (rhs.org.uk) — Hylomecon vernalis']::text[], 'Papavero dei boschi, della famiglia delle Papaveracee, originario dell''Estremo Oriente. È una perenne cespitosa, alta una trentina di centimetri, che si allarga lentamente; le foglie, quasi tutte alla base, sono verde chiaro e composte da foglioline. Dalla tarda primavera all''estate porta fiori giallo intenso, simili a papaveri, larghi 5 cm. Vuole ombra o mezz''ombra e un terreno fresco ma ben drenato, da neutro ad acido, ricco di sostanza organica: è ideale per un giardino naturale o un angolo di bosco.', 'A clump-forming, spreading perennial to 30cm tall, with pale green mostly basal leaves composed of leaflets and bearing poppy-like deep-yellow flowers 5cm across, from late spring to summer', 'it', '{"luce": "Ombra piena, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce, soprattutto in primavera; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: a fioritura finita, a fine estate o in autunno, si ripulisce dalle parti secche', 'Propagazione: per seme, appena maturo o in autunno, oppure per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 171472'),
('4b7911be-a2b5-56bc-98c2-94ee6b561de1'::uuid, 'd7f098a0-fc7b-4ab7-929a-67d20c4a6290'::uuid, array['RHS (rhs.org.uk) — Phaiophleps nigricans']::text[], 'Perenne della famiglia delle Iridacee, originaria del Cile e dell''Argentina, a lungo nota come Phaiophleps nigricans. Forma cespi di ventagli di foglie strette, da lineari a lanceolate, verde grigio; in estate fusti rigidi ed eretti, alti fino a 80 cm, portano lungo tutta la loro lunghezza mazzetti di fiori giallo pallido a stella. Le foglie vecchie anneriscono, da cui il nome. Vuole sole e un terreno fresco ma ben drenato; teme gli inverni umidi e il freddo eccessivo. Si risemina con abbondanza e può diventare invadente.', 'A clump-forming perennial, to 80cm tall, with fans of grey-green, narrow, linear to lance-shaped leaves. In summer, stiff, upright stems carry clusters of pale yellow, star-shaped flowers along their length', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si tolgono le foglie vecchie e annerite', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 64701'),
('24894397-555d-5b78-8917-f38e34cd18f3'::uuid, '07097b8c-c226-4e6f-a730-ee4efc9889a7'::uuid, array['RHS (rhs.org.uk) — Ornithogalum balansae']::text[], 'Piccola bulbosa della famiglia delle Asparagacee, diffusa dai Balcani all''Iran. Ogni bulbo produce due foglie scanalate, verde medio, lunghe fino a 10 cm; in primavera uno stelo eretto porta un grappolo aperto di fiori bianchi a stella. I bulbi si piantano in autunno, a 10 cm di profondità, in un terreno mediamente fertile e ben drenato, in pieno sole. Adatto al giardino roccioso e ai bordi delle aiuole.', 'A bulbous perennial producing two, channelled, mid-green leaves to 10cm long. In spring it produces an erect flowerstalk bearing an open cluster of starry, white flowers', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme in contenitore in cassone freddo, in autunno o in primavera; oppure staccando i bulbilli durante il riposo']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 11933'),
('1ddbcb91-1cc1-55b7-b3fd-1f44cb1408fa'::uuid, '2afbfceb-16fb-422b-96a5-cb3e003237b3'::uuid, array['RHS (rhs.org.uk) — Paraquilegia microphylla']::text[], 'Piccola perenne alpina della famiglia delle Ranuncolacee, originaria delle montagne dell''Asia centrale e della Cina sud-occidentale. Forma ciuffi alti 10-18 cm di foglie verde azzurro, profondamente divise, lunghe 3 cm. Tra la tarda primavera e l''inizio dell''estate i boccioli color lavanda si aprono in fiori a coppa larghi 2-4 cm, viola azzurro, porpora azzurro, lilla pallido o bianchi, con nettari dorati e antere gialle. È una pianta da intenditori, che può attecchire con difficoltà: all''aperto vuole pieno sole e un terreno povero, calcareo e drenatissimo, in un ghiaione o in una vasca da alpine, al riparo dall''umidità invernale. Cresce meglio dove le estati sono fresche e gli inverni freddi e asciutti.', 'A tufted herbaceous perennial 10-18cm high with blue-green, deeply divided leaves, 3cm long, and lavender-blue buds opening in late spring or early summer to violet-blue, purple-blue, pale lilac, or white cup-shaped flowers, 2-4cm across, with golden nectaries and yellow anthers', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce e, al riparo, ad afidi e ragnetto rosso; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme fresco, appena maturo in autunno, in contenitori all''aperto']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 12311'),
('1c15e588-2580-57d6-a112-848dcdde2a4e'::uuid, 'eded20a4-674e-449c-8f31-afd165faaa4a'::uuid, array['RHS (rhs.org.uk) — Parochetus africanus']::text[], 'Leguminosa della famiglia delle Fabacee, originaria delle montagne dell''Africa tropicale, dall''Etiopia al sud del continente. È una perenne sempreverde che forma tappeti alti una decina di centimetri, con foglie simili a quelle del trifoglio, composte da tre foglioline segnate ciascuna da una macchia bruna a ferro di cavallo. Dall''autunno alla primavera, appena sopra il fogliame, porta fiori azzurri a farfalla larghi 2,5 cm. Vuole un terreno fresco ma ben drenato, all''ombra o a mezz''ombra. Non sopporta il gelo né l''umidità invernale: si coltiva in vaso e si porta al riparo d''inverno, in un terriccio di terra, terriccio di foglie e ghiaino in parti uguali.', 'A mat-forming evergreen perennial to 10cm tall, with clover-like leaves composed of three leaflets, each with a brown horseshoe mark; blue pea-flowers 2.5cm across are held just above the foliage from autumn to spring', 'it', '{"luce": "Ombra piena", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.5-1m', 'Potatura: non richiede potatura', 'Propagazione: per divisione, oppure separando gli stoloni radicati, quando la pianta è in crescita']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 43151'),
('6f05820b-ffab-5f53-92bb-c07ef72496f6'::uuid, 'f3461241-0dc8-4fb2-b198-ee04d68cff82'::uuid, array['RHS (rhs.org.uk) — Bauhinia saigonensis']::text[], 'Rampicante della famiglia delle Fabacee, originaria dell''Indocina, a lungo nota come Bauhinia saigonensis. È un arbusto semisempreverde, sarmentoso, che si arrampica fino a circa 4 m con viticci su fusti sottili. Le foglie sono rotonde e divise in due lobi, verde medio o chiaro, ramate da giovani. In estate porta piccoli mazzi di fiori larghi fino a 5 cm, simili a orchidee, con cinque petali rosa pallido, i tre superiori striati di vene porpora. Vuole pieno sole, un luogo riparato e un terreno fertile, fresco ma ben drenato; non sopporta i geli intensi.', 'A semi-evergreen, spreading, scrambling shrub climbing to around 4m high via twining tendrils on slender stems. Mid- to pale green, rounded leaves are coppery when young and have two lobes. Summer flowers to 5cm across are borne in small clusters and orchid-like in appearance with five pale pink petals, the upper three being striped with purple veins', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -5 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 4-8m', 'Potatura: si accorcia quando serve per contenerla, a fine inverno, tagliando i fusti troppo lunghi e togliendo quelli secchi o rovinati', 'Propagazione: per seme o per propaggine']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 1992'),
('1b009fb9-0bb8-507b-a3b6-b55645184e72'::uuid, '4035f7bb-b937-4739-ac21-ddf879714a7e'::uuid, array['RHS (rhs.org.uk) — Sedum ellacombeanum']::text[], 'Borracina della famiglia delle Crassulacee, originaria del Giappone, a lungo nota come Sedum ellacombeanum. È una succulenta semisempreverde con rizomi, che forma cuscinetti bassi di foglie lucide, verdi, a forma di spatola e dal margine smerlato, che in autunno e in inverno si sfumano di rosso. A fine estate, su fusti brevi, porta mazzetti di fiori gialli a stella che si aprono da boccioli rosa. Vuole pieno sole, un luogo riparato e un terreno mediamente fertile e ben drenato, da neutro a calcareo; è adatta al giardino roccioso e ai vasi.', 'A mound-forming, rhizomatous semi-evergreen perennial, with glossy, spoon-shaped green leaves with scalloped edges, that are flushed with red in autumn and winter. Produces short stems bearing clusters of star-shaped yellow flowers from pink buds in late summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH neutro, alcalino"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: può essere soggetta a marciumi del colletto e delle radici, fungini e batterici', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si spunta per mantenerle la forma', 'Propagazione: per seme in cassone freddo in autunno, oppure in estate per talea di legno tenero dai getti che non hanno fiorito']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 73168'),
('859b9aa6-c15e-5bc7-942d-c2f323d99c52'::uuid, '095907bc-6669-47e1-8deb-4b2d658879a8'::uuid, array['RHS (rhs.org.uk) — Hieracium velutinum']::text[], 'Pelosella della famiglia delle Asteracee, parente stretta della comune pelosella dei prati. È una perenne semisempreverde che forma tappeti alti una ventina di centimetri, allargandosi con stoloni striscianti. Le foglie, in rosetta alla base, sono verde grigio e pelose di sopra, coperte sotto da un feltro bianco e morbido. In estate, su steli senza foglie, porta capolini gialli solitari larghi 2-3 cm, con i fiori del margine segnati sotto da una striscia rossa. In natura cresce nei prati bassi e sui terreni sciolti; in giardino vuole pieno sole e un terreno ben drenato.', 'A mat-forming perennial to about 20cm tall, with creeping stolons and a basal rosette of leaves greyish green and hairy above with downy, white felted undersides. Solitary yellow flowerheads, borne on leafless stems, are 2-3cm across with ray florets marked with a red stripe on the underside, produced in summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 329296'),
('7665718d-491b-545e-a652-c8ec717aa90e'::uuid, 'd6ec7e81-54a2-404e-9d97-23f93de685d0'::uuid, array['RHS (rhs.org.uk) — Pulsatilla grandis']::text[], 'Pulsatilla della famiglia delle Ranuncolacee, originaria dell''Europa centrale e dell''Ucraina. È una perenne bassa, alta una ventina di centimetri, che a inizio primavera apre un fitto mazzo di grandi fiori viola, larghi fino a 9 cm, con un vistoso ciuffo centrale di stami dorati; ai fiori seguono teste di semi piumose e sericee. Le foglie spuntano dopo la fioritura, finemente divise e coperte di peli argentei e setosi. Vuole pieno sole e un terreno molto ben drenato: è adatta al giardino roccioso, ai ghiaioni e alle aiuole di piante alpine. Non ama essere spostata e può attecchire con difficoltà.', 'A perennial to 20cm, producing a dense cluster of purple flowers up to 9cm across with a large boss of golden stamens, in early spring, followed by silky seedheads. The leaves emerge after the flowers and are very finely divided and covered in silky, silvery hairs', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: le lumache possono mangiarne i fiori; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme oppure per talea di radice in inverno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 211507'),
('6c408805-b13a-5aa3-8dab-5bcce9c3d250'::uuid, 'fc980c19-d382-45b1-b3e6-6c576764fedf'::uuid, array['RHS (rhs.org.uk) — Pyrethropsis hosmariense']::text[], 'Margherita del Marocco, della famiglia delle Asteracee, originaria del Marocco. È una perenne dalla base legnosa, alta una trentina di centimetri, che si allarga in cuscini di foglie argentee divise in segmenti sottili; su tutto il cuscino porta, appena sopra il fogliame, margherite bianche solitarie con il centro giallo, per un lungo periodo. Vuole pieno sole e un terreno molto ben drenato, e teme l''umidità invernale: sta bene in un giardino roccioso soleggiato, in un''aiuola rialzata o ai piedi di un muro caldo.', 'A woody-based spreading perennial to 30cm in height, with silvery leaves divided into narrow segments, and solitary yellow-centred white daisies held just above the foliage', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per talea di legno tenero']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 29243'),
('2a7b5240-b5d7-5375-98ba-e78639be7337'::uuid, 'ea589bf7-0f68-4d0e-8a54-65f4d96c20d9'::uuid, array['RHS (rhs.org.uk) — Rhexia alifanus']::text[], 'Perenne della famiglia delle Melastomatacee, originaria degli Stati Uniti sud-orientali, fino al Texas. Ha fusti eretti, lisci, quadrangolari e non ramificati, verde rossastro, alti fino a 120 cm, con foglie lisce e cerose, verde azzurro. Da luglio a settembre porta fiori rosa porpora o magenta, con gli stami gialli e ricurvi. Vuole pieno sole e un terreno acido e sabbioso, sempre umido ma senza ristagni.', 'A tall, upright wildflower, native to Southeast USA, to around 120cm in height, with smooth, waxy, blue-green foliage.  Bright purple-pink to magenta flowers with curved yellow stamens appear on smooth, square, unbranched reddish-green stems from July through to September', 'it', '{"luce": "Pieno sole", "acqua": "Poco drenato", "terreno": "Franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a marciume radicale', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; a inizio primavera, quando spunta la nuova vegetazione, si tagliano a terra i fusti vecchi', 'Propagazione: per seme in casa a fine inverno, premendo i semi sul terriccio senza coprirli, perché per germinare hanno bisogno di luce; oppure per talea di fusto in primavera e in estate, al caldo e con molta umidità']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 543711'),
('996d442e-04cd-5d55-ba82-594769987ae8'::uuid, 'e62e6ca5-1914-484f-af38-5197ecd63992'::uuid, array['RHS (rhs.org.uk) — Seseli carvifolia L.']::text[], 'Ombrellifera della famiglia delle Apiacee, diffusa in gran parte d''Europa. Forma un cespo denso di foglie finemente divise, piumose, di un verde appena azzurrato; in estate fusti eretti e angolosi, alti fino a un metro, portano ombrelle piatte e leggere di minuscoli fiori bianchi a stella. Si adatta a molte condizioni: preferisce un terreno fresco ma ben drenato, al sole o a mezz''ombra. Ha una radice a fittone e non ama essere disturbata: le piantine vanno trapiantate giovani, in vasi profondi.', 'A clump-forming perennial, to 1m high in flower, forming a dense mound of finely divided, feathery, slightly blue-green leaves. In summer, upright angled stems bear flat, lacy clusters of tiny star-shaped white flowers', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: con il secco può essere soggetta a oidio', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: si tolgono le ombrelle sfiorite se non si vogliono i semi', 'Propagazione: per seme, appena maturo, trapiantando le piantine in vasi profondi per non danneggiare il fittone; oppure per divisione a inizio primavera, disturbando le radici il meno possibile']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 315875'),
('fba15de7-7ce3-5b99-9f08-ca54f2b52cfa'::uuid, '78dc34b3-33fb-4d93-adaa-9d54bc21a257'::uuid, array['RHS (rhs.org.uk) — Seseli osseum']::text[], 'Ombrellifera della famiglia delle Apiacee, originaria dell''Europa centrale e orientale. È una pianta eretta, alta intorno agli 80 cm, monocarpica: di solito fiorisce una volta sola e poi muore, dopo aver disseminato. Il fogliame è morbido, finemente diviso come quello di una felce, aromatico e di colore grigio-azzurro. In estate i fusti eretti e ramificati portano ombrelle appiattite di minuscoli fiori bianchi, leggeri come un merletto, belli anche recisi. Vuole pieno sole e un terreno fresco ma ben drenato, da neutro a calcareo; è una scelta ideale per un giardino di ghiaia soleggiato, dove si risemina da sola con generosità.', 'An upright, monocarpic (meaning it will generally flower once then die) umbellifer to around 80cm, with aromatic, soft, ferny blue-grey foliage.  In summer, upright, branching stems bear flattened umbels of tiny, lacy white flowers which can be used in flower arrangements.  An ideal choice for a sunny gravel garden', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'biennale', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme; si risemina spontaneamente con facilità']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 24982'),
('9a82a26b-e09d-5b27-ba5e-b5763bdb6f94'::uuid, '3042e3b6-f059-4ce8-904d-d3b3c11b74ad'::uuid, array['RHS (rhs.org.uk) — Sparaxis fragrans subsp. grandiflora']::text[], 'Pianta bulbosa della famiglia delle Iridacee, originaria della provincia del Capo occidentale, in Sudafrica. Dal cormo, un organo di riserva simile a un bulbo, nasce un ventaglio eretto di foglie a forma di spada; in primavera steli alti fino a 25 cm portano piccoli grappoli di fiori a sei tepali arrotondati, nella forma più coltivata (la sottospecie grandiflora) da porpora a rosso porpora. Non sopporta il gelo: si coltiva in vaso, in un luogo luminoso ma riparato dal sole più caldo, e si porta al riparo d''inverno. I cormi si piantano in autunno, a 20 cm di profondità, in un terriccio a base di terra con sabbia e terriccio di foglie; durante la crescita si annaffia poco e si tiene la pianta al fresco, poi, quando i fiori appassiscono, si sospendono le annaffiature e i cormi riposano completamente all''asciutto.', 'A cormous perennial with sword-shaped leaves forming an erect, basal fan. Small clusters of purple to reddish-purple flowers comprising six tepals with rounded tips are borne on stems up to around 25cm tall', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0-0.1m', 'Potatura: si tolgono gli steli sfioriti e si lascia seccare il fogliame da solo', 'Propagazione: per seme in contenitore in cassone freddo, appena maturo, oppure staccando i cormi figli durante il riposo']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 26/11/2026, schede nuove; pagina RHS 110500');
do $$ declare n int; begin
  select count(*) into n from public.schede where id in ('ff2709fd-258d-5368-a7f0-d985e7f9529b'::uuid, 'd7e3351f-033a-51a6-8ea9-d1b1e16b7c2f'::uuid, 'fb833adb-1c3a-53fe-a5ff-f5ac08c97d5a'::uuid, 'd492d5d3-bad5-5132-b69b-77163a4418bf'::uuid, 'a2c8aea3-7f82-5f33-96ac-dc409b99a58f'::uuid, 'd2545349-9f29-5a11-a181-67de74443025'::uuid, '04d9b0ef-4e6e-5d41-80da-012012b7ea36'::uuid, '64a1af23-c094-59c3-9b07-f650ebc41c8a'::uuid, 'b08d9833-4862-5064-bcd0-10ae6537ec2b'::uuid, '4b7911be-a2b5-56bc-98c2-94ee6b561de1'::uuid, '24894397-555d-5b78-8917-f38e34cd18f3'::uuid, '1ddbcb91-1cc1-55b7-b3fd-1f44cb1408fa'::uuid, '1c15e588-2580-57d6-a112-848dcdde2a4e'::uuid, '6f05820b-ffab-5f53-92bb-c07ef72496f6'::uuid, '1b009fb9-0bb8-507b-a3b6-b55645184e72'::uuid, '859b9aa6-c15e-5bc7-942d-c2f323d99c52'::uuid, '7665718d-491b-545e-a652-c8ec717aa90e'::uuid, '6c408805-b13a-5aa3-8dab-5bcce9c3d250'::uuid, '2a7b5240-b5d7-5375-98ba-e78639be7337'::uuid, '996d442e-04cd-5d55-ba82-594769987ae8'::uuid, 'fba15de7-7ce3-5b99-9f08-ca54f2b52cfa'::uuid, '9a82a26b-e09d-5b27-ba5e-b5763bdb6f94'::uuid);
  if n <> 22 then raise exception 'attese 22 schede, trovate %', n; end if;
end $$;
